// ─── Shared Document Renderer ───────────────────────────────────────────────
export function renderDocument(p, title, bodyContent, documentType = 'Offer Letter', options = {}) {
  const isOfferLetter = documentType === 'Offer Letter';

  // Determine if this document type requires an acknowledgement page
  const ACK_DOC_TYPES = [
    'Offer Letter',
    'Appointment Letter',
    'Confirmation Letter',
    'Increment Letter',
    'Promotion Letter',
    'Full & Final Settlement Letter',
    'Warning Letter',
    'Show Cause Notice',
    'Probation Extension Letter'
  ];
  const requiresAck = ACK_DOC_TYPES.includes(documentType);

  let page2Content = '';
  let page3Content = '';
  if (isOfferLetter) {
        // Page 2 = salary breakdown (only for paid roles)
    if (p.STIPEND !== 'unpaid') {
      page2Content = salaryBreakdownPage(p);
    }
    // Page 3 = acceptance
    page3Content = acceptancePage(p, `I understand and accept the terms outlined in this offer letter${p.DURATION && p.DURATION !== 'four (4) months' ? `, including the duration of ${p.DURATION}` : ''}. Either party may conclude this engagement with the prior notice period mentioned above.`);
  } else if (requiresAck) {
    page2Content = `
<div class="page-2">
  <img src="${LOGO_MARK}" class="wm" alt="">
  ${headerBlock(p.DATE, p.DOC_ID)}
  <div class="content">
    <div class="acc-title">ACKNOWLEDGEMENT &amp; ACCEPTANCE</div>
    <div class="acc-body">
      <p>I, <strong>${p.NAME}</strong>, hereby acknowledge receipt of this <strong>${documentType}</strong> reference number <strong>${p.DOC_ID}</strong>. I have read, understood, and accept the terms and guidelines outlined therein.</p>
      <p>I confirm my signature to this acknowledgement as confirmation of receipt and understanding.</p>
      <p>Sincerely,</p>
    </div>
    <div style="margin-top:18px">
      <div class="acc-field">
        <label>Signature:</label>
        <div class="field-line"></div>
      </div>
      <div class="acc-field" style="align-items:center">
        <label>Name:</label>
        <strong style="font-size:11pt">${p.NAME}</strong>
      </div>
      <div class="acc-field">
        <label>Date:</label>
        <div class="field-line"></div>
      </div>
    </div>
    <div class="sig" style="margin-top:22px">
      <p>Authorized Signatory details and corporate signature are attached to the primary document.</p>
      <p style="margin-top:8px">Sincerely,</p>
      <div class="sig-image-container">
        <img src="${SIGNATURE}" class="sig-image" alt="Signature">
      </div>
      <div class="sig-line">
        <p><strong>Authorized Signatory</strong></p>
        <p>Corvus Studio</p>
      </div>
    </div>
  </div>
  ${FOOTER}
</div>`;
  }

  // Render sub-titles only for relevant letters with role/department
  const NO_SUBTITLE_DOCS = [
    'Warning Letter',
    'Show Cause Notice',
    'Salary Certificate',
    'Employment Verification Certificate',
    'No Objection Certificate (NOC)',
    'Experience Letter'
  ];
  const showSubtitle = !NO_SUBTITLE_DOCS.includes(documentType);

  const page1Content = `
<div class="offer-title">${title.toUpperCase()}</div>
${showSubtitle && p.ROLE ? `<div class="offer-sub">${p.ROLE} &mdash; ${p.DEPT}</div>` : ''}
<div class="body">
  ${bodyContent}
</div>
${sigBlock()}`;

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>${documentType} — Corvus Studio</title>
<style>${CSS}</style>
</head>
<body>
<div class="page">
  <img src="${LOGO_MARK}" class="wm" alt="">
  ${headerBlock(p.DATE, p.DOC_ID)}
  <div class="content">
${page1Content}
  </div>
  ${FOOTER}
</div>
${page2Content}
${page3Content}
</body>
</html>`;
}

// ─── Header Block ─────────────────────────────────────────────────────────────
function headerBlock(date, docId = '') {
  return `
<div class="top-stripe"></div>
<div class="header">
  <div class="header-left">
    <img src="${LOGO_FULL}" class="header-logo-full" alt="Corvus Studio">
  </div>
  <div class="header-right">
    <div class="header-tagline">Motion that <b>Speaks.</b></div>
    ${docId ? `<div class="header-docid">Ref: <b>${docId}</b></div>` : ''}
    <div class="header-date">Date: <b>${date}</b></div>
  </div>
</div>
<hr class="header-line">`;
}

// ─── Footer Block ─────────────────────────────────────────────────────────────
const FOOTER = `
<div class="footer">
  <strong>YASH CORPORATION</strong><br>
  Shop No - 04, ALPHONNE COMPLEX, NR PRIMARY SCHOOL, JHALIRAJDA, Junagadh, Gujarat, 360022
</div>`;


// ─── Page 2: Salary Breakdown ────────────────────────────────────────────────
function salaryBreakdownPage(p) {
  const ctc        = Number(p.MONTHLY_CTC || p.STIPEND) || 0;
  const annual     = Number(p.ANNUAL_CTC)  || ctc * 12;
  const basic      = Number(p.BASIC_SALARY) || Math.round(ctc * 0.4);
  const hra        = Number(p.HRA)          || Math.round(ctc * 0.2);
  const special    = Number(p.SPECIAL_ALLOWANCE) || Math.max(0, ctc - basic - hra);
  const employerPF = Number(p.EMPLOYER_PF) || Math.round(basic * 0.12);
  const employeePF = Number(p.EMPLOYEE_PF) || Math.round(basic * 0.12);
  const gross      = basic + hra + special;
  const deductions = employeePF;
  const net        = gross - deductions;

  // PF Maturity calculation (3 years @ 8.25% p.a. compounded monthly)
  const monthlyPF  = employeePF + employerPF;      // total monthly PF corpus contribution
  const annualPF   = monthlyPF * 12;
  const pfRate     = 8.25 / 100 / 12;              // monthly rate
  const pfMonths   = 36;                            // 3 years (36 months)
  const pfMaturity = Math.round(monthlyPF * (((Math.pow(1 + pfRate, pfMonths) - 1) / pfRate) * (1 + pfRate)));

  const fmt = n => Math.round(n).toLocaleString('en-IN');

  return `
<div class="page-2">
  <img src="${LOGO_MARK}" class="wm" alt="">
  ${headerBlock(p.DATE, p.DOC_ID)}
  <div class="content">
    <div class="acc-title">SALARY BREAKDOWN</div>
    <div class="acc-body">
      <p>This document sets out the detailed salary structure for <strong>${p.NAME}</strong> in the role of <strong>${p.ROLE}</strong>, effective from <strong>${p.JOINING}</strong>.</p>
    </div>

    <table class="breakdown-table">
      <thead>
        <tr><th colspan="2">Earnings</th><th colspan="2">Deductions (From Salary Share)</th></tr>
        <tr>
          <td class="label">Component</td><td class="amount">Monthly (INR)</td>
          <td class="label">Component</td><td class="amount">Monthly (INR)</td>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td>Basic Salary</td><td class="amount">&#8377;&nbsp;${fmt(basic)}</td>
          <td>Employee PF (12% of Basic)</td><td class="amount">&#8377;&nbsp;${fmt(employeePF)}</td>
        </tr>
        <tr>
          <td>House Rent Allowance (HRA)</td><td class="amount">&#8377;&nbsp;${fmt(hra)}</td>
          <td></td><td></td>
        </tr>
        <tr>
          <td>Special Allowance</td><td class="amount">&#8377;&nbsp;${fmt(special)}</td>
          <td></td><td></td>
        </tr>
      </tbody>
      <tfoot>
        <tr class="total-row">
          <td>Gross Salary</td><td class="amount">&#8377;&nbsp;${fmt(gross)}</td>
          <td>Total Deductions</td><td class="amount">&#8377;&nbsp;${fmt(deductions)}</td>
        </tr>
        <tr class="net-row">
          <td colspan="2"><strong>Monthly CTC (INR)</strong></td>
          <td colspan="2" class="amount"><strong>&#8377;&nbsp;${fmt(ctc)}</strong></td>
        </tr>
        <tr class="net-row highlight">
          <td colspan="2"><strong>Net Monthly Salary (Take-Home)</strong></td>
          <td colspan="2" class="amount net-amount"><strong>&#8377;&nbsp;${fmt(net)}</strong></td>
        </tr>
        <tr class="net-row">
          <td colspan="2">Annual CTC</td>
          <td colspan="2" class="amount">&#8377;&nbsp;${fmt(annual)}</td>
        </tr>
      </tfoot>
    </table>

    <!-- Employer Contributions Section -->
    <div class="pf-section" style="margin-top:10px">
      <div class="pf-title">EMPLOYER CONTRIBUTIONS (INCLUDED IN CTC)</div>
      <table class="breakdown-table" style="margin-top:6px">
        <thead>
          <tr>
            <th>Contribution Component</th>
            <th class="amount" style="width:25%">Monthly (INR)</th>
            <th>Type</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>Employer PF (12% of Basic)</td>
            <td class="amount">&#8377;&nbsp;${fmt(employerPF)}</td>
            <td>Statutory Share (Not Deducted from Take-Home Salary)</td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- PF Maturity Section -->
    <div class="pf-section" style="margin-top:10px">
      <div class="pf-title">PROVIDENT FUND SUMMARY</div>
      <table class="breakdown-table" style="margin-top:6px">
        <thead>
          <tr><th colspan="2">PF Contribution Details</th><th colspan="2">PF Maturity Projection</th></tr>
        </thead>
        <tbody>
          <tr>
            <td>Monthly Employee PF</td><td class="amount">&#8377;&nbsp;${fmt(employeePF)}</td>
            <td>Total Monthly PF (Employee + Employer)</td><td class="amount">&#8377;&nbsp;${fmt(monthlyPF)}</td>
          </tr>
          <tr>
            <td>Monthly Employer PF</td><td class="amount">&#8377;&nbsp;${fmt(employerPF)}</td>
            <td>Annual PF Contribution</td><td class="amount">&#8377;&nbsp;${fmt(annualPF)}</td>
          </tr>
          <tr class="net-row highlight">
            <td>Total Monthly PF</td><td class="amount">&#8377;&nbsp;${fmt(monthlyPF)}</td>
            <td><strong>Estimated PF Value After 3 Years (@ Current EPF Interest Rate)</strong></td><td class="amount net-amount"><strong>&#8377;&nbsp;${fmt(pfMaturity)}</strong></td>
          </tr>
        </tbody>
      </table>
    </div>

    <div class="breakdown-note" style="font-size:8.2pt; line-height:1.35; margin-top:8px">
      <p><strong>Compliance Note (EPF Act, 1952):</strong> In accordance with the Employees' Provident Funds and Miscellaneous Provisions Act, 1952, employees are entitled to EPF benefits. Under standard Indian payroll structuring, the employer's matching contribution of 12% of Basic is included within the gross Cost to Company (CTC). Deductions from the employee's gross monthly salary are limited strictly to the employee's own statutory share (12% of Basic) and any applicable tax/professional tax, ensuring full alignment with the Payment of Wages Act, 1936.</p>
      <p style="margin-top:4px"><strong>Disclaimer:</strong> The PF projection is an estimate based on the current EPF interest rate and assumes uninterrupted monthly contributions for 3 years. Actual accumulated PF will depend on the EPFO-declared interest rates, the timing of monthly contributions, salary revisions, and statutory rules. If the employee resigns or leaves the organization before completing 3 years, the accumulated PF balance, including eligible employer contributions and accrued interest as per EPFO regulations, can be transferred to a new employer or withdrawn subject to the applicable EPFO rules in force at that time.</p>
    </div>
  </div>
  ${FOOTER}
</div>`;
}

